<?php
require_once __DIR__ . '/config/auth.php'; require_login();
$stmt = $pdo->prepare('SELECT b.*, e.name AS equipment_name, e.category FROM bookings b JOIN equipment e ON e.id = b.equipment_id WHERE b.user_id = ? ORDER BY b.booking_date DESC, b.start_time DESC'); $stmt->execute([$_SESSION['user_id']]); $bookings = $stmt->fetchAll();
$pageTitle = 'My bookings'; require __DIR__ . '/includes/header.php';
?><section class="page-intro container"><p class="eyebrow">YOUR SCHEDULE</p><h1>My bookings.</h1><p>Keep your reserved training time close.</p></section><section class="table-wrap container"><?php if (!$bookings): ?><div class="empty-state"><h2>No bookings yet.</h2><p>Choose a station and reserve your first session.</p><a class="button button-primary" href="equipment.php">Browse equipment</a></div><?php else: ?><table><thead><tr><th>Equipment</th><th>Date</th><th>Time</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($bookings as $booking): ?><tr><td><strong><?= e($booking['equipment_name']) ?></strong><small><?= e($booking['category']) ?></small></td><td><?= e(date('M j, Y', strtotime($booking['booking_date']))) ?></td><td><?= e(date('g:i A', strtotime($booking['start_time']))) ?> - <?= e(date('g:i A', strtotime($booking['end_time']))) ?></td><td><span class="status <?= $booking['status'] === 'confirmed' ? 'available' : 'cancelled' ?>"><?= e(ucfirst($booking['status'])) ?></span></td><td><?php if ($booking['status'] === 'confirmed' && ($booking['booking_date'] . ' ' . $booking['start_time']) > date('Y-m-d H:i:s')): ?><form method="post" action="cancel_booking.php"><input type="hidden" name="booking_id" value="<?= (int) $booking['id'] ?>"><button class="text-button" type="submit" data-confirm="Cancel this booking?">Cancel</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></section><?php require __DIR__ . '/includes/footer.php'; ?>
